class FakeDB:
    def __init__(self, unread):
        self.unread = dict(unread)
        self.calls = 0

    def count_unread(self, user_id):
        self.calls += 1
        return self.unread.get(user_id, 0)


class ProfileService:
    """The unread-message badge, cached because every page asks for it."""

    def __init__(self, cache, db):
        self.cache = cache
        self.db = db

    def unread_count(self, user_id):
        return self.cache.get_or_load(user_id, self.db.count_unread)

